Voici un exemple de code pour un bot Discord à l'aide de Discord.js v14 qui dispose d'une commande "bannir" :

```javascript
const { Client, GatewayIntentBits } = require('discord.js');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

client.once('ready', () => {
  console.log('Bot Discord prêt !');
});

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const { commandName } = interaction;

  if (commandName === 'bannir') {
    if (!interaction.memberPermissions?.has('BAN_MEMBERS')) {
      return interaction.reply({
        content: 'Vous n'avez pas la permission de bannir les utilisateurs !',
        ephemeral: true,
      });
    }

    const member = interaction.mentions.members.first();

    if (!member) {
      return interaction.reply({
        content: 'Veuillez mentionner un utilisateur à bannir !',
        ephemeral: true,
      });
    }

    if (!member.bannable) {
      return interaction.reply({
        content: 'Je ne peux pas bannir cet utilisateur !',
        ephemeral: true,
      });
    }

    await interaction.member.ban(member.user.id, {
      days: 7,
      reason: 'Commande bannir',
    });

    interaction.reply({
      content: `**${member.user.tag}** a été banni avec succès !`,
    });
  }
});

client.login(process.env.TOKEN);
```

Ce code crée un bot Discord avec une commande "bannir". Pour utiliser cette commande, il faut que l'utilisateur ait la permission de bannir les utilisateurs dans le serveur Discord. Le bot vérifie également si l'utilisateur à bannir est mentionné avant de le bannir.

Remarque : N'oubliez pas de remplacer `process.env.TOKEN` par votre propre clé de bot Discord.

Voici une fonction C++ qui prend une référence à un std::string contenant du texte au format Markdown et renvoie un std::string contenant du texte au format HTML :

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <boost/algorithm/string.hpp> // pour la fonction boost::trim

std::string markdown_to_html(const std::string& markdown) {
    std::stringstream html;

    // Conversion des titres
    std::string title = boost::trim_copy(markdown.substr(0, 3));
    if (title == "#") {
        html << "<h1>" << markdown.substr(3) << "</h1>";
    } else if (title == "##") {
        html << "<h2>" << markdown.substr(3) << "</h2>";
    } else if (title == "###") {
        html << "<h3>" << markdown.substr(3) << "</h3>";
    } else if (title == "####") {
        html << "<h4>" << markdown.substr(4) << "</h4>";
    } else if (title == "#####") {
        html << "<h5>" << markdown.substr(5) << "</h5>";
    } else if (title == "######") {
        html << "<h6>" << markdown.substr(6) << "</h6>";
    } else {
        html << markdown;
    }

    // Conversion des titres en italiques
    std::string italic = boost::trim_copy(markdown.substr(1));
    if (italic == "_") {
        html << "<em>" << markdown.substr(2) << "</em>";
    } else {
        html << markdown;
    }

    // Conversion des titres en gras
    std::string bold = boost::trim_copy(markdown.substr(2));
    if (bold == "**") {
        html << "<strong>" << markdown.substr(3) << "</strong>";
    } else {
        html << markdown;
    }

    // Conversion des liens
    std::size_t pos = markdown.find_first_of("[");
    while (pos != std::string::npos) {
        std::string link = markdown.substr(pos, markdown.find_first_of("]", pos) - pos + 1);
        std::string url = markdown.substr(markdown.find_first_of("(", pos) + 1, markdown.find_first_of(")", pos) - markdown.find_first_of("(", pos) - 1);
        html << "<a href=\"" << url << "\">" << link << "</a>";
        pos = markdown.find_first_of("[", pos + 1);
    }

    // Conversion des listes
    std::string list = boost::trim_copy(markdown.substr(0, 2));
    if (list == "-") {
        html << "<ul>";
        std::size_t pos = markdown.find_first_of("\n", 2);
        while (pos != std::string::npos) {
            html << "<li>" << markdown.substr(2, pos - 2) << "</li>";
            pos = markdown.find_first_of("\n", pos + 1);
        }
        html << "</ul>";
    } else if (list == "+") {
        html << "<ul class=\"disc\">";
        std::size_t pos = markdown.find_first_of("\n", 2);
        while (pos != std::string::npos) {
            html << "<li>" << markdown.substr(2, pos - 2) << "</li>";
            pos = markdown.find_first_of("\n", pos + 1);
        }
        html << "</ul>";
    } else if (list == "*") {
        html << "<ul class=\"square\">";
        std::size_t pos = markdown.find_first_of("\n", 2);
        while (pos != std::string::npos) {
            html << "<li>" << markdown.substr(2, pos - 2) << "</li>";
            pos = markdown.find_first_of("\n", pos + 1);
        }
        html << "</ul>";
    } else {
        html << markdown;
    }

    // Conversion des codes
    std::string code = boost::trim_copy(markdown.substr(3));
    if (code.size() > 0 && code[0] == '`') {
        html << "<pre><code>" << markdown.substr(4, markdown.find_last_of("`\n") - 4) << "</code></pre>";
    } else {
        html << markdown;
    }

    return html.str();
}

int main() {
    std::string markdown = "Hello **world**! \n\n# Titre H1\n## Titre H2\n### Titre H3\n#### Titre H4\n##### Titre H5\n###### Titre H6\n\n- Item 1\n- Item 2\n- Item 3\n\n+ Item 1\n+ Item 2\n+ Item 3\n\n* Item 1\n* Item 2\n* Item 3\n\n`code example`";
    std::string html = markdown_to_html(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

Cette fonction utilise les bibliothèques Boost pour la fonction `boost::trim` qui permet de supprimer les espaces blancs en début et en fin de chaîne. Elle utilise également la fonction `std::stringstream` pour générer le texte HTML progressivement. 

La fonction convertit les titres, les titres en italiques, les titres en gras, les liens, les listes et les codes en HTML. Il est possible d'étendre cette fonction pour gérer d'autres éléments de Markdown, selon vos besoins.

