int main() {
    string motSpecifique; // Mot à rechercher dans le fichier
    int count = 0; // Compteur des occurrences du mot

    // Demander à l'utilisateur le mot à rechercher
    cout << "Entrez le mot à rechercher : ";
    getline(cin, motSpecifique);

    // Ouverture du fichier texte
    ifstream file("fichier_texte.txt");

    if (!file) {
        cout << "Erreur : Impossible d'ouvrir le fichier." << endl;
        return 1;
    }

    // Lire le contenu du fichier ligne par ligne
    string ligne;
    while (getline(file, ligne)) {
        // Chercher le mot dans la ligne courante
        size_t position = ligne.find(motSpecifique);
        while (position != string::npos) {
            count++; // Incrémentation du compteur
            position = ligne.find(motSpecifique, position + 1); // Rechercher le mot suivant
        }
    }

    // Fermeture du fichier
    file.close();

    // Afficher le résultat
    cout << "Le mot \"" << motSpecifique << "\" apparaît " << count << " fois dans le fichier." << endl;

    return 0;
}
